-- table: sys_permission（由 cmd/schema-split 生成；改结构直接改本文件）

-- @phase pre
CREATE SEQUENCE public.sys_permission_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

-- @phase ddl
CREATE TABLE public.sys_permission (
    id bigint NOT NULL,
    permission_code character varying(100) NOT NULL,
    permission_name character varying(100) NOT NULL,
    module character varying(50) NOT NULL,
    api_path character varying(200) NOT NULL,
    api_method character varying(10) DEFAULT 'GET'::character varying NOT NULL,
    status smallint DEFAULT 1 NOT NULL,
    remark character varying(200),
    create_by bigint DEFAULT 0 NOT NULL,
    create_time timestamp with time zone,
    update_by bigint DEFAULT 0 NOT NULL,
    update_time timestamp with time zone
);

ALTER SEQUENCE public.sys_permission_id_seq OWNED BY public.sys_permission.id;

ALTER TABLE ONLY public.sys_permission ALTER COLUMN id SET DEFAULT nextval('public.sys_permission_id_seq'::regclass);

-- @phase constr
ALTER TABLE ONLY public.sys_permission
    ADD CONSTRAINT sys_permission_pkey PRIMARY KEY (id);

ALTER TABLE ONLY public.sys_permission
    ADD CONSTRAINT uk_sys_permission_code UNIQUE (permission_code);

-- @phase idx
CREATE INDEX idx_sys_permission_module ON public.sys_permission USING btree (module);

CREATE INDEX idx_sys_permission_status ON public.sys_permission USING btree (status);

-- @phase comment
COMMENT ON TABLE public.sys_permission IS '权限点表（非 Casbin 策略表）';

COMMENT ON COLUMN public.sys_permission.permission_code IS '权限编码，如 admin:list';

COMMENT ON COLUMN public.sys_permission.module IS '所属模块';

COMMENT ON COLUMN public.sys_permission.api_path IS '后端接口路径';

COMMENT ON COLUMN public.sys_permission.api_method IS '请求方法 GET/POST';

COMMENT ON COLUMN public.sys_permission.status IS '状态：0禁用 1启用';

COMMENT ON COLUMN public.sys_permission.create_time IS '审计 DB-018：由 timestamp 统一为 timestamptz；历史值按会话时区解释';

COMMENT ON COLUMN public.sys_permission.update_time IS '审计 DB-018：由 timestamp 统一为 timestamptz；历史值按会话时区解释';

